INSERT INTO articulos (
  id,
  autor_id,
  categoria_id,
  titulo,
  slug,
  contenido,
  extracto,
  imagen_destacada,
  estado,
  etiquetas,
  metadata
) VALUES (
  gen_random_uuid(),
  COALESCE((SELECT id FROM perfiles WHERE rol_id = 1 LIMIT 1), (SELECT id FROM perfiles LIMIT 1)),
  NULL,
  'Rescate del Prisionero',
  'rescate-del-prisionero',
  '<h2>📜 Descripción de Rescate del Prisionero</h2><p><strong>Rescate del Prisionero</strong> es un emblemático juego nocturno de acecho, sigilo y estrategia en equipo. Los guardianes han atado a un prisionero scout a un árbol central en medio del bosque o campo. El objetivo de la patrulla es infiltrarse silenciosamente en la oscuridad para desatar sus nudos y liberar al compañero sin ser detectados por el haz de luz del guardián.</p><hr><h3>🎲 ¿Cómo se juega Rescate del Prisionero?</h3><ol><li><strong>Preparación y Roles:</strong> Un participante asume el rol de prisionero y es atado de forma segura pero fácil de desatar a un árbol. Uno o dos dirigentes o guiadoras actúan como guardianes, ubicándose a unos 10 pasos del árbol. El resto de la patrulla se desplaza a una distancia de entre 50 y 100 metros en la penumbra.</li><li><strong>El Acecho Nocturno:</strong> A la señal de inicio, los acosadores avanzan en completo silencio entre los arbustos y la vegetación, aprovechando el relieve del terreno y la penumbra para acercarse al prisionero.</li><li><strong>Reglas de la Linterna:</strong> Los guardianes permanecen en su zona fija y sólo pueden encender la linterna por ráfagas breves de 2 a 3 segundos cuando escuchen un ruido sospechoso. Si el haz de luz alumbra directamente a un jugador y el guardián dice su nombre, ese jugador queda descubierto y debe regresar a la línea de salida.</li><li><strong>Victoria y Liberación:</strong> El juego concluye con éxito cuando uno o varios acosadores logran llegar hasta el árbol sin ser vistos, desatan el pañolín o la cuerda del prisionero y lo escoltan fuera de la zona de custodia.</li></ol>',
  'Un apasionante juego nocturno scout de acecho y sigilo donde la patrulla debe infiltrarse en la oscuridad para liberar a un compañero prisionero.',
  '/uploads/rescate-del-prisionero.webp',
  'publicado',
  ARRAY['juego nocturno', 'acecho', 'sigilo', 'estrategia', 'cooperacion'],
  '{"areas": ["corporalidad", "creatividad"], "lugares": ["Exterior", "campo abierto"], "cantidad": "Toda la Unidad", "duracion": "45 minutos", "unidades": ["tropa", "compañía", "avanzada"], "descargas": [], "objetivos": ["Estimular la capacidad de reacción", "Estimular la atención a los detalles", "Desarrollar el carácter mediante la cooperación", "Perder el miedo a la oscuridad"], "materiales": ["Linternas", "Cuerdas", "Pañolines"], "variaciones": "<b>Prisionero Múltiple:</b> Se atan dos o tres prisioneros en distintos puntos del campo delimitado, obligando a la patrulla a dividirse en sub-equipos de rescate para actuar en paralelo.\n\n<b>Silencio de Linternas:</b> Los guardianes no disponen de linternas pero pueden lanzar preguntas en voz alta o pequeñas alarmas sonoras; los acosadores deben responder congelando su posición de inmediato.\n\n<b>Rescate por Claves:</b> Para desatar al prisionero no basta con soltar la cuerda, sino que deben resolver una clave morse o semáforo que el prisionero lleva consigo.", "recomendaciones": "<b>Seguridad en el Terreno Nocturno:</b> Inspeccionar previamente el campo de juego durante el día para identificar y delimitar hoyos, ramas bajas, zanjas o zonas de riesgo.\n\n<b>Uso Responsable de Linternas:</b> Limitar la cantidad de encendidos de linterna por parte de los guardianes para mantener el clima de misterio y evitar encandilar a los participantes.\n\n<b>Contención Emocional:</b> Acompañar suavemente a los scouts más jóvenes para que superen el temor natural a la penumbra en un entorno amigable y seguro.", "justificacion_areas": "El Rescate del Prisionero estimula la corporalidad y la creatividad táctica mediante el desplazamiento sigiloso y la resolución ágil de problemas en la penumbra. Al coordinarse en equipo para burlar la atención de los guardianes y desenvolverse con destreza física en la naturaleza, los jóvenes fortalecen su agilidad mental y su desarrollo corporal armónico.", "objetivos_educativos": [{"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "unidad": "Compañía", "como_se_cumple": "Respetando las reglas de sigilo y límites del terreno durante el acecho nocturno."}, {"id": "12686e7d-d6af-4c74-928d-c859d5b883d5", "area": "Creatividad", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Participando en la discusión y análisis del plan de aproximación silenciosa en equipo."}, {"id": "2d033cc1-87bb-4990-846e-bbac8a4249fe", "area": "Corporalidad", "texto": "Ayudo a preparar los juegos, excursiones y campamentos de mi patrulla y mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Participando activamente en la estrategia de aproximación y distracción para rescatar al prisionero."}, {"id": "e0c02bfe-4056-4d1b-b0b1-013bda1fffa6", "area": "Creatividad", "texto": "Organizo actividades novedosas para realizar con mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Ideando tácticas creativas en equipo para desorientar el haz de luz de los guardianes."}, {"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "unidad": "Tropa", "como_se_cumple": "Respetando las reglas de sigilo y zonas de avance en la penumbra."}, {"id": "e465926e-deed-4341-956f-047f56860e5e", "area": "Creatividad", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Aportando ideas para coordinar las señales sordas entre los acosadores de la patrulla."}, {"id": "6768d60a-187e-4bbf-97b9-cdc25a316030", "area": "Corporalidad", "texto": "Ayudo a preparar los juegos, excursiones y campamentos de mi patrulla y mi Tropa.", "unidad": "Tropa", "como_se_cumple": "Desplazándome con agilidad física y destreza corporal entre la vegetación nocturna."}, {"id": "d287b1bf-76a7-4c41-8ddf-fb5c83a4fa3b", "area": "Creatividad", "texto": "Organizo actividades novedosas para realizar con mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Proponiendo maniobras sorpresa para liberar al prisionero sin ser descubiertos."}, {"id": "7200435f-b020-46fc-b323-8249048b1d18", "area": "Corporalidad", "texto": "Participo en la organización de juegos y actividades recreativas para los demás.", "unidad": "Avanzada", "como_se_cumple": "Coordinando el despliegue del equipo de rescate con liderazgo y visión del espacio nocturno."}, {"id": "310eb631-8ca9-4eaf-ac80-232a5150d024", "area": "Creatividad", "texto": "Creo actividades y juegos para realizar con mi comunidad y soy capaz de motivarlos.", "unidad": "Avanzada", "como_se_cumple": "Liderando con iniciativa y agilidad mental la táctica final para desatar los nudos del prisionero."}]}'::jsonb
);

